    /// Localized form name, or nullptr when there is none for this language.
    const char *getFormNameLocalized(uint16_t speciesId, uint8_t formId, size_t languageIndex)
    {
        if (languageIndex >= LANGUAGE_COUNT)
            return nullptr;
        constexpr size_t count = sizeof(LOCALIZED_FORM_NAMES) / sizeof(LOCALIZED_FORM_NAMES[0]);
        size_t low = 0, high = count;
        while (low < high)
        {
            const size_t middle = low + (high - low) / 2;
            const LocalizedFormName &row = LOCALIZED_FORM_NAMES[middle];
            if (row.species < speciesId || (row.species == speciesId && row.form < formId))
                low = middle + 1;
            else if (row.species == speciesId && row.form == formId)
                return row.names[languageIndex];
            else
                high = middle;
        }
        return nullptr;
    }
